pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        uint256 beforeSecond;
        try c.MinSum() returns (uint256 __r) { beforeSecond = __r; } catch { return; }
        bool firstReverted;
        try c.SetMinSum(firstVal) { firstReverted = false; } catch { firstReverted = true; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        bool secondReverted;
        try c.SetMinSum(secondVal) { secondReverted = false; } catch { secondReverted = true; }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue(!firstReverted && !secondReverted == false ? false : true);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
        _run(firstVal, secondVal);
    }

    receive() external payable {}
}
